export const STAT_KEYS = ['hp', 'attack', 'defense', 'sp_attack', 'sp_defense', 'speed'];
export const STAT_MAX = 255;

// The base stat total is on its own scale, not 6 x STAT_MAX: 6 x 120 is the
// in-game ceiling and also the highest total in our data, so scoring against
// 1530 would leave every bar under 47% and read as broken.
export const TOTAL_MAX = 720;

export const STAT_LABELS = {
  hp: 'HP',
  attack: '攻擊',
  defense: '防禦',
  sp_attack: '特攻',
  sp_defense: '特防',
  speed: '速度'
};

export { TYPE_CHART, TYPE_CHART_ORDER, TYPE_CHART_SOURCE } from './type-chart.js';

/** Attacking types, in the order the wiki grid lists them. */
export const ATTACKING_TYPES = TYPE_CHART_ORDER;

/** Damage multipliers that actually occur, strongest first. */
export const EFFECT_BUCKETS = [
  { multiplier: 4, label: '致命弱點', suffix: '4×' },
  { multiplier: 2, label: '弱點', suffix: '2×' },
  { multiplier: 0.5, label: '抗性', suffix: '½×' },
  { multiplier: 0.25, label: '極抗性', suffix: '¼×' },
  { multiplier: 0, label: '免疫', suffix: '0×' }
];

/**
 * Resolve how each attacking type fares against the given defender type(s).
 * The two defender rows are multiplied, so a 1/2 against one type cancelling a
 * 2x against the other lands on 1x and drops out, while 4x / 1/4x / 0x fall out
 * on their own. Anything that ends up neutral is omitted.
 * @returns {Array<{multiplier:number,label:string,suffix:string,types:Array<{en:string,zh:string}>}>}
 */
export function typeEffectiveness(defenderTypes) {
  const rows = ATTACKING_TYPES.map(attacker => {
    let multiplier = 1;
    for (const defender of defenderTypes) {
      const row = TYPE_CHART[attacker] || {};
      multiplier *= row[defender] === undefined ? 1 : row[defender];
    }
    return { attacker, multiplier };
  });

  return EFFECT_BUCKETS
    .map(bucket => ({
      ...bucket,
      types: rows
        .filter(row => row.multiplier === bucket.multiplier)
        .map(row => ({ en: row.attacker, zh: TYPE_EN_ZH[row.attacker] || row.attacker }))
    }))
    .filter(bucket => bucket.types.length > 0);
}

/**
 * Traditional Chinese category (分類) for a Pokémon.
 * Ids in GENUS_ZH_BY_ID pin entries the wiki renders inconsistently.
 */
export function genusZh(pokemon) {
  if (!pokemon) return '—';
  if (GENUS_ZH_BY_ID[pokemon.id]) return GENUS_ZH_BY_ID[pokemon.id];
  if (GENUS_EN_ZH[pokemon.genus]) return GENUS_EN_ZH[pokemon.genus];
  if (!pokemon.genus) return '—';
  return `${String(pokemon.genus).replace(/\s*Pokémon$/, '')}寶可夢`;
}

/** Look up a value in a label map, falling back to the raw value. */
export function labelZh(map, value) {
  if (!value) return '—';
  if (map[value]) return map[value];
  return String(value).replace(/-/g, ' ');
}
